{"path":"about.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>About — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f7efe6;--accent:#7a4b2b;--muted:#6b6b6b;--card:#fff;--glass:rgba(255,255,255,0.6)}
    *{box-sizing:border-box}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;line-height:1.45;margin:0;background:linear-gradient(180deg,var(--bg),#efe6db);color:#222}
    header{display:flex;align-items:center;justify-content:space-between;padding:1.25rem 1.5rem;background:transparent}
    .brand{display:flex;align-items:center;gap:.75rem}
    .logo{width:48px;height:48px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#b06b48);display:grid;place-items:center;color:#fff;font-weight:700}
    nav a{margin-left:1rem;color:var(--muted);text-decoration:none;font-weight:600}
    .hero{padding:2rem 1.5rem;display:grid;gap:1rem;grid-template-columns:1fr;align-items:center}
    .hero-inner{max-width:900px}
    h1{font-size:1.85rem;margin:0;color:var(--accent)}
    p.lead{margin:.5rem 0;color:var(--muted)}

    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:1rem;padding:1rem}
    .card{background:var(--card);padding:1rem;border-radius:12px;box-shadow:0 6px 18px rgba(30,20,10,0.06)}
    .small{font-size:.95rem;color:var(--muted)}

    .cta-row{display:flex;gap:.75rem;margin-top:1rem}
    .btn{display:inline-flex;align-items:center;gap:.5rem;padding:.6rem .9rem;border-radius:8px;border:0;cursor:pointer;font-weight:700}
    .btn.primary{background:var(--accent);color:#fff}
    .btn.ghost{background:transparent;border:2px solid rgba(0,0,0,0.05)}

    footer{padding:2rem 1.5rem;color:var(--muted);font-size:.95rem}

    /* guided exercise modal */
    .modal-backdrop{position:fixed;inset:0;display:none;align-items:center;justify-content:center;background:linear-gradient(180deg,rgba(0,0,0,0.35),rgba(0,0,0,0.45));z-index:60}
    .modal{width:min(680px,94%);background:var(--card);border-radius:14px;padding:1.25rem;box-shadow:0 12px 40px rgba(20,10,0,0.25)}
    .modal h2{margin:.25rem 0}
    .steps{display:grid;gap:.75rem}
    .step{padding:.75rem;border-radius:10px;background:var(--glass)}
    .timer{display:flex;align-items:center;gap:.75rem}
    .circle{width:56px;height:56px;border-radius:50%;background:conic-gradient(var(--accent) 0deg,var(--bg) 0deg);display:grid;place-items:center;color:#fff;font-weight:700}

    /* animated reveal */
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .7s ease,transform .7s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){
      .reveal{transition:none;opacity:1;transform:none}
      .circle{transition:none}
    }

    /* small utilities */
    .muted{color:var(--muted)}
    .micro{font-size:.85rem;color:var(--muted)}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <div class="logo">SB</div>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div class="micro">{{TAGLINE}}</div>
      </div>
    </div>
    <nav aria-label="Primary Navigation">
      <a href="index.html">Start</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="hero-inner">
        <h1 class="reveal">About the work</h1>
        <p class="lead reveal">We shape simple frameworks for rest using sonic textures, guided attention, and practical rituals you can carry with you. Sessions are crafted to help you soften toward presence and leave with a clearer orientation.</p>
        <div class="cta-row reveal">
          <button class="btn primary" id="open-guided">Try a short exercise</button>
          <a class="btn ghost" href="book.html">Reserve a space</a>
        </div>
      </div>
    </section>

    <section class="grid" aria-label="Principles">
      <article class="card reveal">
        <h3>What we return to</h3>
        <p class="small">Rhythm, texture, and steady attention. We use layered tones and light cues to support an inward arc—from settling, through release, to arrival.</p>
      </article>

      <article class="card reveal">
        <h3>Where it fits</h3>
        <p class="small">Evening gatherings, mid-day resets, and brief private sessions for specific intentions like sleep preparation or mental clarity.</p>
      </article>

      <article class="card reveal">
        <h3>Who should check in</h3>
        <p class="small">People looking for a focused container to practice letting go. Please review contraindications in our FAQ before attending.</p>
      </article>
    </section>

    <section class="card" style="margin:1rem;padding:1rem;max-width:900px;margin-left:auto;margin-right:auto;" aria-labelledby="process-title">
      <h2 id="process-title" class="reveal">Our approach</h2>
      <ol class="small reveal">
        <li>Arrival & grounding: brief orientation and intention-setting.</li>
        <li>Layered sound: guided tones, breath cues, and rests.</li>
        <li>Integration: journaling prompts and optional sharing.</li>
      </ol>
      <p class="micro reveal">Sessions run on a steady arc—you can step into the rhythm and step back out with tools to continue at home.</p>
    </section>
  </main>

  <footer>
    <div class="small">Questions? Call <a href="tel:{{PHONE}}">{{PHONE}}</a> or email <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</div>
    <div class="micro">Serving {{CITY}}, {{STATE}} — <a href="book.html">{{PRIMARY_CTA_LABEL}}</a></div>
  </footer>

  <!-- Guided exercise modal -->
  <div id="modal" class="modal-backdrop" aria-hidden="true">
    <div class="modal" role="dialog" aria-modal="true" aria-labelledby="modal-title">
      <button id="close-modal" style="float:right;border:0;background:transparent;font-size:1.1rem;cursor:pointer">✕</button>
      <h2 id="modal-title">Try a brief practice</h2>
      <p class="micro">A guided three-part exercise: breathing, quick journaling, and an intention prompt. Designed for a 6–8 minute pocket reset.</p>
      <div class="steps">
        <div class="step" data-step="1">
          <strong>Breath (2 minutes)</strong>
          <div class="timer" style="margin-top:.5rem">
            <div class="circle" id="breath-circle">2:00</div>
            <div class="small">Follow the visual circle as it fills and empties. Inhale on the rise, exhale on the fall.</div>
          </div>
        </div>
        <div class="step" data-step="2">
          <strong>Journaling (3 minutes)</strong>
          <div class="small" style="margin-top:.5rem">Write freely about how your body is right now. No judgments—two to three lines is plenty.</div>
          <textarea id="journal" rows="4" style="width:100%;margin-top:.5rem;border-radius:8px;padding:.6rem;border:1px solid #e6e1dc"></textarea>
        </div>
        <div class="step" data-step="3">
          <strong>Set an intention (30s)</strong>
          <div class="small" style="margin-top:.5rem">Choose a word or short sentence you can repeat during the day.</div>
          <div style="margin-top:.5rem">
            <input id="intention" placeholder="e.g. steady, open, patient" style="width:100%;padding:.5rem;border-radius:8px;border:1px solid #e6e1dc">
          </div>
        </div>
      </div>
      <div style="display:flex;gap:.5rem;margin-top:.75rem;justify-content:flex-end">
        <button class="btn" id="cancel">Close</button>
        <button class="btn primary" id="start">Begin</button>
      </div>
    </div>
  </div>

  <script>
    // Modal flow and breathing timer
    (function(){
      const modal = document.getElementById('modal');
      const open = document.getElementById('open-guided');
      const close = document.getElementById('close-modal');
      const cancel = document.getElementById('cancel');
      const start = document.getElementById('start');
      const breathCircle = document.getElementById('breath-circle');
      const journal = document.getElementById('journal');
      const intention = document.getElementById('intention');
      let timerId=null;

      function showModal(){ modal.style.display='flex'; modal.setAttribute('aria-hidden','false'); }
      function hideModal(){ modal.style.display='none'; modal.setAttribute('aria-hidden','true'); clearInterval(timerId); breathCircle.style.background='conic-gradient(var(--accent) 0deg,var(--bg) 0deg)'; breathCircle.textContent='2:00'; }

      open.addEventListener('click',showModal);
      close.addEventListener('click',hideModal);
      cancel.addEventListener('click',hideModal);

      start.addEventListener('click',function(){
        // three part timing: 120s breath, 180s journaling, 30s intention
        const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        // Breath timer
        let t=120;
        breathCircle.textContent = formatTime(t);
        if(!reducedMotion){
          const stepDeg = 360 / 120; // per second
          breathCircle.style.background = `conic-gradient(var(--accent) ${0}deg, var(--bg) 0deg)`;
          timerId = setInterval(()=>{
            t--;
            if(t<=0){ clearInterval(timerId); startJournal(); return; }
            breathCircle.textContent = formatTime(t);
            const deg = (120 - t) * stepDeg;
            breathCircle.style.background = `conic-gradient(var(--accent) ${deg}deg, var(--bg) ${deg}deg)`;
          },1000);
        } else {
          // reduced motion: skip visual timer, use setTimeout
          breathCircle.style.background = 'none';
          timerId = setTimeout(startJournal,120000);
        }
      });

      function startJournal(){
        // show journaling step and start 3-minute timer in textarea placeholder
        const step2 = document.querySelector('[data-step="2"]');
        step2.scrollIntoView({behavior:'smooth',block:'center'});
        const reducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        let t=180;
        const origPlaceholder = journal.placeholder;
        journal.focus();
        journal.placeholder = 'Write for 3 minutes...';
        if(!reducedMotion){
          let id = setInterval(()=>{
            t--;
            if(t<=0){ clearInterval(id); startIntention(); return; }
            journal.placeholder = `Time left: ${Math.ceil(t/60)}:${String(t%60).padStart(2,'0')}`;
          },1000);
        } else {
          setTimeout(startIntention,180000);
        }
      }

      function startIntention(){
        const step3 = document.querySelector('[data-step="3"]');
        step3.scrollIntoView({behavior:'smooth',block:'center'});
        intention.focus();
        setTimeout(()=>{
          alert('Practice complete. Carry your intention gently through the day.');
          hideModal();
        },30000);
      }

      function formatTime(seconds){const m=Math.floor(seconds/60);const s=seconds%60;return `${m}:${String(s).padStart(2,'0')}`}
    })();

    // Scroll-trigger reveal with prefers-reduced-motion
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('visible')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){ e.target.classList.add('visible'); io.unobserve(e.target); }
        });
      },{threshold:0.12});
      items.forEach(i=>io.observe(i));
    })();
  </script>
</body>
</html>"} 
{"path":"faq.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>FAQ — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fff7f0;--accent:#6b462d;--muted:#4d4d4d;--card:#fff}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;margin:0;background:linear-gradient(180deg,var(--bg),#f1e7de);color:#222}
    header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem}
    .logo{width:42px;height:42px;border-radius:10px;background:linear-gradient(135deg,var(--accent),#a05f40);display:grid;place-items:center;color:#fff;font-weight:800}
    nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
    main{padding:1rem}
    h1{color:var(--accent);font-size:1.5rem}
    .faq{max-width:900px;margin:0 auto}
    .item{background:var(--card);padding:1rem;border-radius:10px;margin-bottom:.7rem;box-shadow:0 8px 24px rgba(30,20,10,0.05)}
    .q{display:flex;justify-content:space-between;cursor:pointer;align-items:center}
    .a{margin-top:.5rem;display:none;color:var(--muted)}
    .a.open{display:block}
    .muted{color:var(--muted)}

    .disclaimer{margin-top:1rem;padding:.9rem;border-radius:10px;background:#fff3ee;border-left:4px solid #e2a88a}

    .try{display:flex;gap:.5rem;margin-top:1rem}
    .btn{padding:.5rem .8rem;border-radius:8px;border:0;cursor:pointer;font-weight:700}
    .btn.primary{background:var(--accent);color:#fff}
    .search{width:100%;padding:.6rem;border-radius:10px;border:1px solid #efe6dc;margin-bottom:.75rem}

    .reveal{opacity:0;transform:translateY(10px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:.8rem"><div class="logo">SB</div><div style="font-weight:700">{{BUSINESS_NAME}}</div></div>
    <nav>
      <a href="index.html">Start</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <section class="faq">
      <h1 class="reveal">Common questions</h1>
      <input id="search" class="search reveal" placeholder="Search the FAQs" aria-label="Search FAQs">

      <div class="item reveal">
        <div class="q" data-target="a1"><strong>What should I bring?</strong><span class="muted">Show me</span></div>
        <div id="a1" class="a">Bring a yoga mat or blanket, a small pillow if you like, water, and comfortable layers. We provide bolsters and shared blankets upon request.</div>
      </div>

      <div class="item reveal">
        <div class="q" data-target="a2"><strong>How long does a gathering last?</strong><span class="muted">Time</span></div>
        <div id="a2" class="a">Most gatherings run 60–75 minutes: a short welcome, a guided sound arc, then gentle reintegration. Private sessions vary from 45 to 90 minutes.</div>
      </div>

      <div class="item reveal">
        <div class="q" data-target="a3"><strong>Are sessions suitable for beginners?</strong><span class="muted">Beginner-friendly</span></div>
        <div id="a3" class="a">Yes. Sessions are accessible and invite curiosity. We offer gentle orientation for first-time guests and options to rest at any point.</div>
      </div>

      <div class="disclaimer reveal">
        <strong>Contraindications & safety</strong>
        <p class="muted">If you are pregnant, have a diagnosis of epilepsy, severe cardiovascular conditions, or are currently undergoing certain psychiatric treatments, please consult your healthcare provider before attending. If you use implanted medical devices, check with your clinician about exposure to sustained vibrations. This practice is not a substitute for medical care.</p>
        <p class="muted">If in doubt, contact us at <a href="mailto:{{EMAIL}}">{{EMAIL}}</a> to discuss accommodations.</p>
      </div>

      <div style="margin-top:1rem" class="reveal">
        <h3>Session-specific questions</h3>
        <div class="item">
          <div class="q" data-target="a4"><strong>Can I fall asleep?</strong><span class="muted">Yes</span></div>
          <div id="a4" class="a">Sleeping is fine. The intention is not to stay awake but to come away more rested. If necessary, we’ll gently wake guests after the closing tone.</div>
        </div>

        <div class="item">
          <div class="q" data-target="a5"><strong>Are there refunds or transfers?</strong><span class="muted">Policy</span></div>
          <div id="a5" class="a">We offer transfers up to 48 hours before an event. For private bookings, see the reservation page for details or contact us directly.</div>
        </div>
      </div>

      <div class="try reveal" style="margin-top:1rem">
        <button class="btn primary" id="open-guided">Try a short exercise</button>
        <a class="btn" href="book.html">Reserve a session</a>
      </div>
    </section>
  </main>

  <script>
    // Simple accordion + search
    document.querySelectorAll('.q').forEach(btn=>{
      btn.addEventListener('click',()=>{
        const id = btn.getAttribute('data-target');
        const el = document.getElementById(id);
        el.classList.toggle('open');
      });
    });

    document.getElementById('search').addEventListener('input',function(e){
      const q = e.target.value.toLowerCase();
      document.querySelectorAll('.item').forEach(item=>{
        const text = item.innerText.toLowerCase();
        item.style.display = text.includes(q) ? '' : 'none';
      });
    });

    // Insert the guided exercise modal used on other pages
    (function(){
      // create minimal modal markup and reuse the logic from about.html
      const open = document.getElementById('open-guided');
      open && open.addEventListener('click',function(){
        // create a lightweight guided prompt instead of full modal to avoid duplication
        const reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
        const proceed = confirm('Start a 6-minute guided breathing and journaling practice now?');
        if(!proceed) return;
        if(!reduced){ alert('Begin breathing: inhale gently for 4s, exhale for 6s. Continue for 2 minutes.'); setTimeout(()=>{ alert('Now: 3 minutes of free writing.'); setTimeout(()=>{ alert('Finish: choose an intention and repeat it silently for 30s.'); },180000); },120000); }
        else{ alert('Start with mindful breaths for a moment, then a brief journaling prompt.'); }
      });
    })();

    // Scroll reveal (duplicate implementation to satisfy repeated feature request)
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('visible')); return; }
      const obs = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{ if(e.isIntersecting){ e.target.classList.add('visible'); obs.unobserve(e.target); } });
      },{threshold:.12});
      items.forEach(i=>obs.observe(i));
    })();
  </script>
</body>
</html>"} 
{"path":"book.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Reserve — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#f5efe8;--accent:#6e4a32;--muted:#555}
    body{font-family:system-ui,-apple-system,Segoe UI,Roboto,Helvetica,Arial;margin:0;background:linear-gradient(180deg,var(--bg),#efe7dc);color:#222}
    header{display:flex;align-items:center;justify-content:space-between;padding:1rem 1.25rem}
    nav a{margin-left:1rem;color:var(--muted);text-decoration:none}
    main{padding:1rem;max-width:900px;margin:0 auto}
    h1{color:var(--accent)}
    .buckets{display:grid;grid-template-columns:1fr 340px;gap:1rem}
    .form-card{background:#fff;padding:1rem;border-radius:12px;box-shadow:0 10px 30px rgba(20,10,0,0.06)}
    label{display:block;margin-top:.6rem;font-weight:700}
    input,select,textarea{width:100%;padding:.6rem;border-radius:8px;border:1px solid #efe6dc;margin-top:.25rem}
    .note{font-size:.9rem;color:var(--muted)}
    .submit{margin-top:1rem;padding:.7rem 1rem;border-radius:10px;border:0;background:var(--accent);color:#fff;font-weight:800;cursor:pointer}
    .options{display:grid;gap:.6rem}
    .pkg{padding:.7rem;border-radius:10px;background:#fff;border:1px solid #f0e7df}
    .price{font-weight:800;color:var(--accent)}

    .reveal{opacity:0;transform:translateY(10px);transition:opacity .6s ease,transform .6s ease}
    .reveal.visible{opacity:1;transform:none}
    @media (prefers-reduced-motion: reduce){.reveal{transition:none;opacity:1;transform:none}}
  </style>
</head>
<body>
  <header>
    <div style="display:flex;align-items:center;gap:.8rem"><div style="width:40px;height:40px;border-radius:10px;background:linear-gradient(135deg,#6e4a32,#b07452);display:grid;place-items:center;color:#fff;font-weight:800">SB</div><div style="font-weight:700">{{BUSINESS_NAME}}</div></div>
    <nav>
      <a href="index.html">Start</a>
      <a href="events.html">Gatherings</a>
      <a href="private-sessions.html">Solo Sessions</a>
      <a href="pricing.html">Invest</a>
      <a href="about.html">About</a>
      <a href="faq.html">FAQ</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Contact</a>
    </nav>
  </header>

  <main>
    <h1 class="reveal">Reserve your space</h1>
    <p class="note reveal">Choose a session type and a time. We keep group sizes intimate and encourage arriving 10 minutes early.</p>

    <div class="buckets">
      <div>
        <form id="bookingForm" class="form-card reveal" novalidate>
          <label for="name">Full name</label>
          <input id="name" name="name" required>

          <label for="email">Email</label>
          <input id="email" name="email" type="email" required>

          <label for="phone">Phone</label>
          <input id="phone" name="phone" type="tel">

          <label for="service">Select offering</label>
          <select id="service" name="service">
            <option value="gathering">Evening Gathering — rhythm & rest</option>
            <option value="solo">Solo Session — focused recalibration</option>
            <option value="series">Elemental Wave Package — 3-session series</option>
          </select>

          <label for="date">Preferred date & time</label>
          <input id="date" name="date" type="datetime-local">

          <label for="notes">Notes or accommodations</label>
          <textarea id="notes" name="notes" rows="4" placeholder="Let us know about mobility, sensitivities, or anything else"></textarea>

          <div style="display:flex;gap:.5rem;align-items:center;margin-top:.75rem">
            <input type="checkbox" id="agree" required>
            <label for="agree" class="note">I have read the <a href="faq.html">contraindications</a> and confirm this booking is safe for me.</label>
          </div>

          <button class="submit" type="submit">Request reservation</button>
        </form>

        <div class="card" style="margin-top:.75rem;padding:.75rem;border-radius:10px;background:#fff"> 
          <strong>What happens next?</strong>
          <p class="note">We’ll review your request and confirm availability by email within 24 hours. For urgent requests call <a href="tel:{{PHONE}}">{{PHONE}}</a>.</p>
        </div>
      </div>

      <aside class="reveal">
        <div class="form-card" style="display:flex;flex-direction:column;gap:.6rem">
          <h3>Offerings & investment</h3>
          <div class="options">
            <div class="pkg">
              <div style="display:flex;justify-content:space-between;align-items:center"><div>Evening Gathering</div><div class="price">$28</div></div>
              <div class="note">A single communal session. Sliding-scale available.</div>
            </div>

            <div class="pkg">
              <div style="display:flex;justify-content:space-between;align-items:center"><div>Solo Session</div><div class="price">$95</div></div>
              <div class="note">One-on-one session tailored to a theme—rest, clarity, or sleep prep.</div>
            </div>

            <div class="pkg">
